def _compact(expression):
    # Ignore whitespace in CEL syntax, never inside string literals.
    compact = []
    quote = None
    escaped = False
    for char in expression:
        if quote is not None:
            compact.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
        elif char in ('"', "'"):
            quote = char
            compact.append(char)
        elif not char.isspace():
            compact.append(char)
    if quote is not None:
        raise Unavailable("CEL string literal malformed")
    return "".join(compact)

